package engine

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Sentinel tag format: `<arbitron:result:NONCE>{...}</arbitron:result:NONCE>`
// where NONCE is a per-instance unguessable identifier generated by the
// executor.
//
// SECURITY (PR #8 thread 3291943275): with --dangerously-skip-permissions the
// agent can echo arbitrary file contents into its own text. A static sentinel
// tag would let an attacker stage a file whose contents look like a completed
// session and have it parsed as the workflow result. The per-instance nonce
// prevents that — a pre-staged file will not contain the runtime-generated
// nonce.
const (
	sentinelOpenPrefix  = "<arbitron:result:"
	sentinelOpenSuffix  = ">"
	sentinelClosePrefix = "</arbitron:result:"
	sentinelCloseSuffix = ">"
)

// SentinelOpenTag builds the per-instance opening tag.
func SentinelOpenTag(nonce string) string {
	return sentinelOpenPrefix + nonce + sentinelOpenSuffix
}

// SentinelCloseTag builds the per-instance closing tag.
func SentinelCloseTag(nonce string) string {
	return sentinelClosePrefix + nonce + sentinelCloseSuffix
}

// extractSentinelResult scans agent output for completion sentinel blocks
// bearing the given nonce and parses the LAST complete (open,close) pair.
// Parsing is left-to-right so spurious or attacker-staged half-blocks
// elsewhere in the output cannot shadow a legitimate completion (PR #8
// thread 3291907751).
//
// ok is false when no nonce-bearing sentinel pair is present. A non-nil error
// means a complete pair was found but its payload was not valid JSON, OR the
// nonce was empty (defensive: an empty nonce reduces back to the static-tag
// attack surface).
func extractSentinelResult(text, nonce string) (map[string]any, bool, error) {
	if nonce == "" {
		return nil, false, fmt.Errorf("engine: sentinel nonce is required")
	}

	openTag := SentinelOpenTag(nonce)
	closeTag := SentinelCloseTag(nonce)

	// Walk left-to-right, remembering the LAST complete pair.
	var lastPayload string
	var haveAny bool
	cursor := 0
	for {
		openIdx := strings.Index(text[cursor:], openTag)
		if openIdx < 0 {
			break
		}
		absOpen := cursor + openIdx
		searchStart := absOpen + len(openTag)
		closeIdx := strings.Index(text[searchStart:], closeTag)
		if closeIdx < 0 {
			// Unmatched open — stop scanning; partial blocks are not parsed.
			break
		}
		absClose := searchStart + closeIdx
		lastPayload = strings.TrimSpace(text[searchStart:absClose])
		haveAny = true
		cursor = absClose + len(closeTag)
	}
	if !haveAny {
		return nil, false, nil
	}

	var out map[string]any
	if err := json.Unmarshal([]byte(lastPayload), &out); err != nil {
		return nil, false, fmt.Errorf("engine: parse interactive result sentinel: %w", err)
	}
	return out, true, nil
}

// sentinelInstruction returns the text appended to an interactive agent's
// prompt telling it how to complete the session. nonce is the per-instance
// unguessable identifier; schema is the node's outputSchema (may be nil).
func sentinelInstruction(nonce string, schema any) string {
	var b strings.Builder
	b.WriteString("\n\nWhen the conversation has reached its conclusion and you ")
	b.WriteString("have the final result, emit exactly one line:\n")
	b.WriteString(SentinelOpenTag(nonce))
	b.WriteString("{...}")
	b.WriteString(SentinelCloseTag(nonce))
	b.WriteString("\nwhere {...} is a JSON object")
	if schema != nil {
		if schemaJSON, err := json.Marshal(schema); err == nil {
			b.WriteString(" conforming to this schema:\n")
			b.Write(schemaJSON)
		}
	}
	b.WriteString("\n")
	return b.String()
}
